from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                        not seen[yy][xx] and grid[yy][xx] == color):
                        seen[yy][xx] = True
                        q.append((yy, xx))
            if any(x == 0 for _, x in cells):
                comps.append((color, cells, max(x for _, x in cells)))

    # Rows with a left-connected component reaching the row's rightmost
    # colored point cast a ray to the right edge.
    for color, cells, comp_right in comps:
        rows = {r for r, _ in cells}
        for r in rows:
            right = max(c for c, v in enumerate(grid[r]) if v != bg)
            if right >= comp_right:
                for c in range(right + 1, w):
                    out[r][c] = 1

    # In a checker-patterned continuation, extend the matching color cells.
    for color, cells, comp_right in comps:
        for r, row in enumerate(grid):
            if row[0] != color:
                continue
            right = max(c for c, v in enumerate(row) if v != bg)
            if right >= comp_right:
                continue
            for pattern in grid:
                for start in range(w - 3):
                    if all(pattern[c] != bg and pattern[c] != pattern[c + 1]
                           for c in range(start, start + 3)):
                        for c in range(max(comp_right + 1, start), w):
                            if pattern[c] == color and grid[r][c] == bg:
                                out[r][c] = 1
                        break

    return out
