        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue

            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                            not seen[yy][xx] and grid[yy][xx] == color):
                            seen[yy][xx] = True
                            q.append((yy, xx))

            # Only extend shapes connected to the left edge.
            if not any(x == 0 for _, x in component):
                continue

            by_row = {}
            for y, x in component:
                by_row.setdefault(y, []).append(x)

            for y, xs in by_row.items():
                xs.sort()
                longest = run = 1
                for i in range(1, len(xs)):
                    run = run + 1 if xs[i] == xs[i - 1] + 1 else 1
                    longest = max(longest, run)

                # A sufficiently long horizontal segment indicates a ray.
                if longest >= 3:
                    for x in range(max(xs) + 1, w):
                        if grid[y][x] == background:
                            out[y][x] = 1

    return out
